import { useNitroApp } from "nitropack/runtime";
export function useServerPDFMake() {
  return useNitroApp().$pdfMake;
}
export function createPDFBuffer(docDefinition) {
  return useServerPDFMake().createPdf(docDefinition).getBuffer();
}
export function createPDFBase64(docDefinition) {
  return useServerPDFMake().createPdf(docDefinition).getBase64();
}
